mapper.select:
SELECT id, user_id, emotion, emotion_label, title, content, images, is_public, create_time, update_time
FROM diary
WHERE id = #{id}

mapper.update:
UPDATE diary
emotion = #{emotion}, emotion_label = #{emotionLabel}, title = #{title}, content = #{content}, images = #{images}, is_public = #{isPublic},
WHERE id = #{id}
